// ---------------------------------------------------------------------------
// Shared API utilities for public storefront endpoints
// ---------------------------------------------------------------------------

export const CORS_HEADERS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

export const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;

/**
 * Return a JSON response with CORS headers attached.
 */
export function corsJson(data: unknown, init?: { status?: number; headers?: Record<string, string> }): Response {
  return Response.json(data, {
    status: init?.status ?? 200,
    headers: { ...CORS_HEADERS, ...init?.headers },
  });
}

/**
 * Handle OPTIONS preflight requests.
 */
export function corsOptions(): Response {
  return new Response(null, { status: 204, headers: CORS_HEADERS });
}

/**
 * Validate a Shopify shop domain. Returns an error response if invalid, or null if valid.
 */
export function validateShop(shop: string | null): Response | null {
  if (!shop || !SHOP_RE.test(shop)) {
    return corsJson({ error: "Invalid or missing shop parameter" }, { status: 400 });
  }
  return null;
}

/**
 * Sanitize user-provided CSS to prevent XSS vectors.
 */
export function sanitizeCss(css: string): string {
  if (!css) return "";
  return css
    .replace(/@import\s/gi, "/* blocked */ ")
    .replace(/url\s*\(\s*["']?\s*javascript:/gi, "url(#")
    .replace(/url\s*\(\s*["']?\s*data:\s*text\/html/gi, "url(#")
    .replace(/expression\s*\(/gi, "/* blocked */(")
    .replace(/behavior\s*:/gi, "/* blocked */:")
    .replace(/-moz-binding\s*:/gi, "/* blocked */:")
    .replace(/-ms-filter\s*:/gi, "/* blocked */:")
    .replace(/<\/style/gi, "/* blocked */")
    .replace(/<script/gi, "/* blocked */");
}

