import { Banner, Button } from "@shopify/polaris";

interface PlanGateProps {
  feature: string;
  requiredPlan: string;
  onUpgrade: () => void;
}

export function PlanGate({ feature, requiredPlan, onUpgrade }: PlanGateProps) {
  return (
    <Banner
      tone="warning"
      title={`Upgrade to ${requiredPlan} to unlock ${feature}`}
      action={{ content: `Upgrade to ${requiredPlan}`, onAction: onUpgrade }}
    >
      <p>
        {feature} is available on the {requiredPlan} plan and above.
        Upgrade to start using this feature.
      </p>
    </Banner>
  );
}

import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  Box,
  Tooltip,
  Divider,
  TextField,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";
import {
  getAnalyticsSummary,
  getConversionFunnel,
  getTopCharts,
  getDailyTrend,
  buildDateRange,
  type AnalyticsSummary,
  type ConversionFunnel,
  type ChartPerformance,
  type DailyDataPoint,
} from "../lib/analytics.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface AnalyticsData {
  summary: AnalyticsSummary;
  summaryPrev: AnalyticsSummary;
  funnel: ConversionFunnel;
  topCharts: ChartPerformance[];
  dailyTrend: DailyDataPoint[];
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const url = new URL(request.url);
  const fromParam = url.searchParams.get("from");
  const toParam = url.searchParams.get("to");
  const presetParam = url.searchParams.get("preset") ?? "30d";

  // Resolve current date range
  const now = new Date();
  let fromDate: Date;
  let toDate: Date = new Date(now);
  toDate.setHours(23, 59, 59, 999);

  if (fromParam && toParam) {
    fromDate = new Date(fromParam);
    fromDate.setHours(0, 0, 0, 0);
    const parsedTo = new Date(toParam);
    parsedTo.setHours(23, 59, 59, 999);
    toDate = parsedTo;
  } else {
    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
    fromDate.setHours(0, 0, 0, 0);
  }

  const dateRange = { from: fromDate, to: toDate };

  // Previous period for trend comparison (same duration, shifted back)
  const rangeMs = toDate.getTime() - fromDate.getTime();
  const prevToDate = new Date(fromDate.getTime() - 1);
  prevToDate.setHours(23, 59, 59, 999);
  const prevFromDate = new Date(prevToDate.getTime() - rangeMs);
  prevFromDate.setHours(0, 0, 0, 0);
  const prevDateRange = { from: prevFromDate, to: prevToDate };

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const plan = getPlan(subscription?.planId ?? "free");
  const canViewAnalytics = hasFeature(plan.id, "analytics");

  if (!canViewAnalytics) {
    return {
      plan,
      canViewAnalytics: false as const,
      analytics: null,
      preset: presetParam,
      fromDate: fromDate.toISOString().split("T")[0],
      toDate: toDate.toISOString().split("T")[0],
    };
  }

  // Fetch all analytics data using the server helpers
  const [summary, summaryPrev, funnel, topCharts, dailyTrend] = await Promise.all([
    getAnalyticsSummary(shop, dateRange),
    getAnalyticsSummary(shop, prevDateRange),
    getConversionFunnel(shop, dateRange),
    getTopCharts(shop, dateRange, 5),
    getDailyTrend(shop, dateRange, "view"),
  ]);

  const analytics: AnalyticsData = {
    summary,
    summaryPrev,
    funnel,
    topCharts,
    dailyTrend,
  };

  return {
    plan,
    canViewAnalytics: true as const,
    analytics,
    preset: presetParam,
    fromDate: fromDate.toISOString().split("T")[0],
    toDate: toDate.toISOString().split("T")[0],
  };
};

// ---------------------------------------------------------------------------
// StatCard — single metric with trend
// ---------------------------------------------------------------------------

function StatCard({
  label,
  value,
  prevValue,
  isLoading,
}: {
  label: string;
  value: number;
  prevValue: number;
  isLoading: boolean;
}) {
  const diff = value - prevValue;
  const pct = prevValue > 0 ? Math.round((diff / prevValue) * 100) : 0;
  const isUp = diff >= 0;

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor="border"
      borderRadius="200"
      padding="400"
    >
      <BlockStack gap="100">
        <Text as="p" variant="bodySm" tone="subdued">{label}</Text>
        <Text as="p" variant="headingXl" fontWeight="bold">
          {isLoading ? "—" : value.toLocaleString()}
        </Text>
        {!isLoading && prevValue > 0 && (
          <InlineStack gap="100" blockAlign="center">
            <Text
              as="span"
              variant="bodySm"
              tone={isUp ? "success" : "critical"}
            >
              {isUp ? "+" : ""}{pct}%
            </Text>
            <Text as="span" variant="bodySm" tone="subdued">vs prior period</Text>
          </InlineStack>
        )}
        {!isLoading && prevValue === 0 && (
          <Text as="p" variant="bodySm" tone="subdued">No prior data</Text>
        )}
      </BlockStack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// BarChart — daily views visualization
// ---------------------------------------------------------------------------

function BarChart({ data, isLoading }: { data: DailyDataPoint[]; isLoading: boolean }) {
  if (isLoading) {
    return (
      <div style={{ height: "250px", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Text as="p" variant="bodyMd" tone="subdued">Loading chart data…</Text>
      </div>
    );
  }

  const max = Math.max(...data.map((d) => d.count), 1);

  // For readability, show at most 30 data points — group into weekly if needed
  let displayData = data;
  if (data.length > 30) {
    const weekBuckets: Record<string, number> = {};
    for (const pt of data) {
      const d = new Date(pt.date + "T12:00:00Z");
      const weekStart = new Date(d);
      weekStart.setDate(d.getDate() - d.getDay());
      const wk = weekStart.toISOString().slice(0, 10);
      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + pt.count;
    }
    displayData = Object.entries(weekBuckets).map(([date, count]) => ({ date, count }));
  }

  const formatLabel = (dateStr: string) =>
    new Date(dateStr + "T12:00:00Z").toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
    });

  return (
    <BlockStack gap="200">
      <div style={{ display: "flex", alignItems: "flex-end", gap: "3px", height: "200px" }}>
        {displayData.map((d, i) => (
          <Tooltip key={i} content={`${formatLabel(d.date)}: ${d.count} views`}>
            <div
              style={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                justifyContent: "flex-end",
                height: "200px",
              }}
            >
              <div
                style={{
                  background: "var(--p-color-bg-fill-brand)",
                  borderRadius: "3px 3px 0 0",
                  height: `${Math.max((d.count / max) * 200, d.count > 0 ? 4 : 0)}px`,
                  minHeight: d.count > 0 ? "4px" : "0",
                  transition: "height 0.2s ease",
                }}
              />
            </div>
          </Tooltip>
        ))}
      </div>
      <InlineStack align="space-between">
        <Text as="p" variant="bodySm" tone="subdued">
          {displayData[0] ? formatLabel(displayData[0].date) : ""}
        </Text>
        <Text as="p" variant="bodySm" tone="subdued">
          {displayData[displayData.length - 1] ? formatLabel(displayData[displayData.length - 1].date) : ""}
        </Text>
      </InlineStack>
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// FunnelStep — single step in the conversion funnel
// ---------------------------------------------------------------------------

function FunnelStep({
  label,
  count,
  rate,
  color,
  isLoading,
}: {
  label: string;
  count: number;
  rate: number;
  color: string;
  isLoading: boolean;
}) {
  const pct = Math.round(rate * 100 * 10) / 10;
  const barWidth = Math.min(100, pct);
  const tone = pct >= 30 ? "success" : pct >= 10 ? "info" : "warning";

  return (
    <BlockStack gap="200">
      <InlineStack gap="300" align="space-between" blockAlign="center">
        <Text as="p" variant="bodyMd">{label}</Text>
        <InlineStack gap="200" blockAlign="center">
          <Text as="p" variant="bodyMd" tone="subdued">
            {isLoading ? "—" : count.toLocaleString()}
          </Text>
          <Badge tone={tone}>{isLoading ? "—" : `${pct}%`}</Badge>
        </InlineStack>
      </InlineStack>
      <Box
        background="bg-fill-secondary"
        borderRadius="150"
        minHeight="8px"
      >
        <div
          style={{
            height: "8px",
            width: `${barWidth}%`,
            background: color,
            borderRadius: "var(--p-border-radius-150)",
            transition: "width 0.4s ease",
          }}
        />
      </Box>
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// TopChartsLeaderboard
// ---------------------------------------------------------------------------

function TopChartsLeaderboard({
  charts,
  isLoading,
  onNavigate,
}: {
  charts: ChartPerformance[];
  isLoading: boolean;
  onNavigate: (id: string) => void;
}) {
  if (isLoading) {
    return (
      <BlockStack gap="200">
        {[1, 2, 3].map((i) => (
          <Box key={i} background="bg-fill-secondary" borderRadius="200" minHeight="44px" />
        ))}
      </BlockStack>
    );
  }

  if (charts.length === 0) {
    return (
      <Text as="p" variant="bodyMd" tone="subdued">
        No chart views in this period. Data appears once customers start viewing your size charts.
      </Text>
    );
  }

  const maxViews = Math.max(...charts.map((c) => c.views), 1);

  return (
    <BlockStack gap="300">
      {charts.map((chart, idx) => (
        <BlockStack key={chart.sizeChartId} gap="150">
          <InlineStack gap="300" blockAlign="center">
            <Box
              background={idx === 0 ? "bg-fill-caution" : idx === 1 ? "bg-fill-secondary" : "bg-fill-tertiary"}
              borderRadius="full"
              minWidth="28px"
              minHeight="28px"
              width="28px"
            >
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "28px" }}>
                <Text as="span" variant="bodySm" fontWeight="bold">{idx + 1}</Text>
              </div>
            </Box>
            <div style={{ flex: 1, minWidth: 0 }}>
              <Button
                variant="plain"
                onClick={() => onNavigate(chart.sizeChartId)}
                textAlign="left"
              >
                {chart.name}
              </Button>
            </div>
            <Text as="p" variant="bodySm" tone="subdued">
              {chart.views.toLocaleString()} views
            </Text>
          </InlineStack>
          <div
            style={{
              height: "4px",
              background: "var(--p-color-bg-fill-brand)",
              borderRadius: "2px",
              width: `${Math.round((chart.views / maxViews) * 100)}%`,
              marginLeft: "40px",
              opacity: 0.6,
            }}
          />
        </BlockStack>
      ))}
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// CSV export helper (runs in browser)
// ---------------------------------------------------------------------------

function exportCsv(data: AnalyticsData, preset: string) {
  const rows: string[] = [
    "Date,Views",
    ...data.dailyTrend.map((pt) => `${pt.date},${pt.count}`),
    "",
    "Metric,Value",
    `Total Views,${data.summary.totalViews}`,
    `Total Clicks,${data.summary.totalClicks}`,
    `Total Recommendations,${data.summary.totalRecommendations}`,
    `Total Conversions,${data.summary.totalConversions}`,
    "",
    "Rank,Chart,Views,Clicks,Recommendations,Conversions",
    ...data.topCharts.map(
      (c, i) =>
        `${i + 1},${c.name},${c.views},${c.clicks},${c.recommendations},${c.conversions}`,
    ),
  ];

  const blob = new Blob([rows.join("\n")], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `size-chart-analytics-${preset}-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const PRESET_OPTIONS = [
  { label: "7 days", value: "7d" },
  { label: "30 days", value: "30d" },
  { label: "90 days", value: "90d" },
];

export default function Analytics() {
  const loaderData = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof loader>();
  const navigate = useNavigate();

  const [activePreset, setActivePreset] = useState(loaderData.preset ?? "30d");
  const [customFrom, setCustomFrom] = useState(loaderData.fromDate);
  const [customTo, setCustomTo] = useState(loaderData.toDate);

  // Use fetcher data after a date-range reload, else use loader data
  const data = fetcher.data ?? loaderData;
  const isLoading = fetcher.state !== "idle";

  function handlePreset(preset: string) {
    setActivePreset(preset);
    fetcher.load(`/app/analytics?preset=${preset}`);
  }

  function handleCustomRange() {
    if (customFrom && customTo) {
      setActivePreset("custom");
      fetcher.load(`/app/analytics?from=${customFrom}&to=${customTo}`);
    }
  }

  // Plan gate
  if (!data.canViewAnalytics) {
    return (
      <Page
        title="Analytics"
        backAction={{ onAction: () => navigate("/app") }}
      >
        <Layout>
          <Layout.Section>
            <BlockStack gap="600">
              <Banner tone="warning" title="Analytics is a Growth plan feature">
                <BlockStack gap="400">
                  <Text as="p" variant="bodyMd">
                    Track how customers interact with your size charts. See chart views,
                    click-through rates, AI recommendation usage, and conversion impact.
                  </Text>
                  <InlineStack gap="400">
                    <Button variant="primary" onClick={() => navigate("/app/pricing")}>
                      Upgrade to Growth — $9.99/mo
                    </Button>
                    <Button onClick={() => navigate("/app/pricing")}>Compare all plans</Button>
                  </InlineStack>
                </BlockStack>
              </Banner>

              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">What you&apos;ll unlock</Text>
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
                      gap: "12px",
                    }}
                  >
                    {[
                      {
                        title: "Chart Views",
                        desc: "See exactly how many customers open your size charts by product and date.",
                      },
                      {
                        title: "Conversion Funnel",
                        desc: "Measure the path from chart view to AI recommendation to add-to-cart.",
                      },
                      {
                        title: "Top Charts",
                        desc: "Identify which size charts drive the most customer engagement.",
                      },
                    ].map((f) => (
                      <Box
                        key={f.title}
                        borderWidth="025"
                        borderColor="border"
                        borderRadius="200"
                        padding="400"
                        background="bg-surface"
                      >
                        <BlockStack gap="100">
                          <Text as="p" variant="bodyMd" fontWeight="semibold">{f.title}</Text>
                          <Text as="p" variant="bodySm" tone="subdued">{f.desc}</Text>
                        </BlockStack>
                      </Box>
                    ))}
                  </div>
                </BlockStack>
              </Card>
            </BlockStack>
          </Layout.Section>
        </Layout>
      </Page>
    );
  }

  const analytics = data.analytics;
  const hasData = analytics !== null && analytics.summary.totalViews > 0;
  const canViewReturnAttribution = hasFeature(data.plan.id, "returnAttribution");

  return (
    <Page
      title="Analytics"
      backAction={{ onAction: () => navigate("/app") }}
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="500">

            {/* ============================================================ */}
            {/* Date Range Bar                                                 */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="300">
                <InlineStack gap="300" align="space-between" blockAlign="center" wrap>
                  {/* Preset buttons */}
                  <InlineStack gap="200" blockAlign="center">
                    {PRESET_OPTIONS.map((opt) => (
                      <Button
                        key={opt.value}
                        size="slim"
                        variant={activePreset === opt.value ? "primary" : undefined}
                        onClick={() => handlePreset(opt.value)}
                        disabled={isLoading}
                      >
                        {opt.label}
                      </Button>
                    ))}
                  </InlineStack>

                  {/* Export */}
                  {hasData && analytics !== null && (
                    <Button
                      size="slim"
                      onClick={() => exportCsv(analytics, activePreset)}
                    >
                      Export CSV
                    </Button>
                  )}
                </InlineStack>

                {/* Custom date inputs */}
                <InlineStack gap="200" blockAlign="end">
                  <div style={{ maxWidth: "160px" }}>
                    <TextField
                      label="From"
                      type="date"
                      value={customFrom}
                      onChange={setCustomFrom}
                      autoComplete="off"
                    />
                  </div>
                  <div style={{ maxWidth: "160px" }}>
                    <TextField
                      label="To"
                      type="date"
                      value={customTo}
                      onChange={setCustomTo}
                      autoComplete="off"
                    />
                  </div>
                  <Button onClick={handleCustomRange} disabled={isLoading}>
                    Apply
                  </Button>
                </InlineStack>
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Pro upsell: Return Attribution                                */}
            {/* ============================================================ */}
            {!canViewReturnAttribution && hasData && (
              <Banner tone="info" title="Unlock Return Attribution — Pro plan">
                <InlineStack gap="400" blockAlign="center">
                  <Text as="p" variant="bodyMd">
                    Connect size chart interactions directly to return rates and see how much
                    revenue your charts protect.
                  </Text>
                  <Button onClick={() => navigate("/app/pricing")}>Upgrade to Pro</Button>
                </InlineStack>
              </Banner>
            )}

            {/* ============================================================ */}
            {/* Empty state                                                    */}
            {/* ============================================================ */}
            {!hasData && analytics !== null && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">
                    No data for this period
                  </Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Analytics data appears as soon as customers view your size charts on the
                    storefront. Make sure your widget is enabled and at least one chart is
                    assigned to a product.
                  </Text>
                  <InlineStack gap="400">
                    <Button variant="primary" onClick={() => navigate("/app/size-charts")}>
                      Manage size charts
                    </Button>
                    <Button onClick={() => navigate("/app/widget")}>Check widget settings</Button>
                  </InlineStack>
                </BlockStack>
              </Card>
            )}

            {/* ============================================================ */}
            {/* Stats Row — 4 metric cards                                    */}
            {/* ============================================================ */}
            {analytics !== null && (
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
                  gap: "12px",
                }}
              >
                <StatCard
                  label="Chart Views"
                  value={analytics.summary.totalViews}
                  prevValue={analytics.summaryPrev.totalViews}
                  isLoading={isLoading}
                />
                <StatCard
                  label="Clicks"
                  value={analytics.summary.totalClicks}
                  prevValue={analytics.summaryPrev.totalClicks}
                  isLoading={isLoading}
                />
                <StatCard
                  label="AI Recommendations"
                  value={analytics.summary.totalRecommendations}
                  prevValue={analytics.summaryPrev.totalRecommendations}
                  isLoading={isLoading}
                />
                <StatCard
                  label="Conversions"
                  value={analytics.summary.totalConversions}
                  prevValue={analytics.summaryPrev.totalConversions}
                  isLoading={isLoading}
                />
              </div>
            )}

            {/* ============================================================ */}
            {/* Daily Trend Chart                                              */}
            {/* ============================================================ */}
            {analytics !== null && (hasData || isLoading) && (
              <Card>
                <BlockStack gap="400">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd" fontWeight="semibold">Daily Views Trend</Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Chart views per day across the selected period
                    </Text>
                  </BlockStack>
                  <BarChart data={analytics.dailyTrend} isLoading={isLoading} />
                </BlockStack>
              </Card>
            )}

            {/* ============================================================ */}
            {/* Conversion Funnel                                              */}
            {/* ============================================================ */}
            {analytics !== null && (hasData || isLoading) && (
              <Card>
                <BlockStack gap="400">
                  <BlockStack gap="100">
                    <Text as="h2" variant="headingMd" fontWeight="semibold">Conversion Funnel</Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      Step-by-step conversion rates from chart view to purchase
                    </Text>
                  </BlockStack>
                  <BlockStack gap="400">
                    <FunnelStep
                      label="Views to Clicks"
                      count={analytics.summary.totalClicks}
                      rate={analytics.funnel.clickRate}
                      color="var(--p-color-bg-fill-brand)"
                      isLoading={isLoading}
                    />
                    <FunnelStep
                      label="Views to AI Recommendations"
                      count={analytics.summary.totalRecommendations}
                      rate={analytics.funnel.recommendRate}
                      color="#2c7be5"
                      isLoading={isLoading}
                    />
                    <FunnelStep
                      label="Views to Conversions"
                      count={analytics.summary.totalConversions}
                      rate={analytics.funnel.convertRate}
                      color="#16a34a"
                      isLoading={isLoading}
                    />
                  </BlockStack>
                </BlockStack>
              </Card>
            )}

            {/* ============================================================ */}
            {/* Top Charts Leaderboard                                         */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Top Size Charts</Text>
                  <Text as="p" variant="bodySm" tone="subdued">Most viewed charts in this period</Text>
