                  charts={analytics?.topCharts ?? []}
                  isLoading={isLoading}
                  onNavigate={(id) => navigate(`/app/size-charts/${id}`)}
                />
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Insights (conditional)                                         */}
            {/* ============================================================ */}
            {hasData && analytics !== null && (
              (() => {
                const clickPct = Math.round(analytics.funnel.clickRate * 100);
                const recommendPct = Math.round(analytics.funnel.recommendRate * 100);
                const showInsights = clickPct < 10 || recommendPct < 20;
                if (!showInsights) return null;
                return (
                  <Card>
                    <BlockStack gap="400">
                      <Text as="h2" variant="headingMd" fontWeight="semibold">Insights</Text>
                      <div
                        style={{
                          display: "grid",
                          gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
                          gap: "12px",
                        }}
                      >
                        {clickPct < 10 && (
                          <Box
                            borderWidth="025"
                            borderColor="border"
                            borderRadius="200"
                            padding="400"
                            background="bg-surface"
                          >
                            <BlockStack gap="150">
                              <Badge tone="warning">Low click rate</Badge>
                              <Text as="p" variant="bodySm" tone="subdued">
                                Below 10% — try moving your widget higher on the product page or
                                switching to a more prominent trigger style.
                              </Text>
                            </BlockStack>
                          </Box>
                        )}
                        {recommendPct < 20 && (
                          <Box
                            borderWidth="025"
                            borderColor="border"
                            borderRadius="200"
                            padding="400"
                            background="bg-surface"
                          >
                            <BlockStack gap="150">
                              <Badge tone="warning">AI underused</Badge>
                              <Text as="p" variant="bodySm" tone="subdued">
                                Fewer than 20% of viewers use the AI recommender. Make sure the
                                recommender is enabled and the button text is clear.
                              </Text>
                            </BlockStack>
                          </Box>
                        )}
                      </div>
                    </BlockStack>
                  </Card>
                );
              })()
            )}

            {/* ============================================================ */}
            {/* Return Attribution upsell (footer)                             */}
            {/* ============================================================ */}
            {!canViewReturnAttribution && (
              <Banner tone="info" title="Unlock Return Attribution">
                <InlineStack gap="400" blockAlign="center">
                  <Text as="p" variant="bodyMd">
                    See which charts reduce returns and calculate revenue saved. Available on Pro plan.
                  </Text>
                  <Button onClick={() => navigate("/app/pricing")}>Upgrade to Pro</Button>
                </InlineStack>
              </Banner>
            )}

          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

