// AlgorithmCard
// ---------------------------------------------------------------------------

function AlgorithmCard({
  id,
  label,
  description,
  badge,
  badgeTone,
  selected,
  disabled,
  onSelect,
}: {
  id: string;
  label: string;
  description: string;
  badge: string;
  badgeTone: "success" | "warning" | "info";
  selected: boolean;
  disabled: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      onClick={() => !disabled && onSelect(id)}
      onKeyDown={(e) => {
        if (!disabled && (e.key === "Enter" || e.key === " ")) {
          e.preventDefault();
          onSelect(id);
        }
      }}
      style={{ cursor: disabled ? "not-allowed" : "pointer", flex: "1 1 0", opacity: disabled ? 0.5 : 1 }}
    >
      <Box
        borderWidth={selected ? "050" : "025"}
        borderColor={selected ? "border-focus" : "border"}
        borderRadius="300"

        background={selected ? "bg-surface-selected" : "bg-surface"}
        padding="400"
      >
        <BlockStack gap="200">
          <InlineStack gap="200" blockAlign="center">
            <Text as="p" variant="bodyMd" fontWeight="semibold">{label}</Text>
            {selected && <Badge tone="info">Active</Badge>}
          </InlineStack>
          <Text as="p" variant="bodySm" tone="subdued">{description}</Text>
          <Badge tone={badgeTone}>{badge}</Badge>
        </BlockStack>
      </Box>
    </div>
  );
}

